import styled from '@emotion/styled';

interface StyledFilterProps {
  $hidden?: boolean;
}

export const StyledFilter = styled.div<StyledFilterProps>(({ $hidden }) => ({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'flex-end',
  alignItems: 'flex-start',
  position: 'relative',
  height: 'max-content',
  ...($hidden && { display: 'none' }),
}));

export const StyledAutoApplyFieldsContainer = styled.div({
  display: 'flex',
  gap: '16px',
  marginBottom: '16px',
});
